/**
 * Phase 1 — product discovery / trend scoring.
 *
 * This module computes a single `trendScore` per product from real signals
 * already generated by existing routes (views, cart adds, wishlist adds,
 * purchases, try-on sessions/conversions, reviews, search impressions). It
 * does not invent, sample, or randomise anything — a brand-new catalogue
 * with no traffic yet correctly scores everything at 0.
 *
 * WHY A CACHED COLUMN INSTEAD OF COMPUTING PER REQUEST
 * Recomputing a decayed sum across six related tables on every storefront
 * page load doesn't scale past a small catalogue. Instead, `recalculate()`
 * runs on a schedule (see src/jobs/recalcTrends.js) and writes the result to
 * Product.trendScore / trendScoreBreakdown / trendScoreComputedAt. Reads are
 * then just `ORDER BY trendScore DESC` — O(log n) with the existing index,
 * regardless of how much history has accumulated.
 *
 * DECAY MODEL
 * Each event contributes weight = exp(-ln(2)/HALF_LIFE_DAYS * ageInDays),
 * i.e. an exponential half-life curve: an event from HALF_LIFE_DAYS ago
 * counts for half as much as one from today, a quarter at 2x the half-life,
 * and so on. Different signal types get different half-lives below —
 * a purchase should matter for longer than a page view.
 *
 * SIGNAL WEIGHTS
 * Relative importance, tuned to be defensible rather than arbitrary: a
 * purchase is worth far more than a view because it's a real transaction,
 * not just interest. These are constants at the top of the file specifically
 * so they can be tuned without touching the query logic.
 */
const { prisma } = require("../db/prisma");

// ---- tuning constants -------------------------------------------------

const HALF_LIFE_DAYS = {
  views: 5,
  searchImpressions: 5,
  cartAdds: 7,
  wishlistAdds: 10,
  tryOns: 7,
  reviews: 21, // a review keeps informing "best rated" for longer than a click does
  purchases: 14,
};

const SIGNAL_WEIGHT = {
  views: 1,
  searchImpressions: 1.5,
  cartAdds: 4,
  wishlistAdds: 3,
  tryOns: 3,
  tryOnConversionBonus: 8, // per converted try-on, in addition to the base tryOns weight
  purchases: 10,
  reviewCountWeight: 2, // per decayed review
  // Deliberately small. Rating is a legitimate trend input (a 5-star product
  // should edge out an identical 4-star one), but at anything close to
  // purchases/cartAdds weight it becomes a static baseline that gives every
  // product a positive score before any real interaction happens — which
  // would make "Trending Now" true for products nobody has looked at. This
  // is sized to be a tiebreaker among products with comparable engagement,
  // not a source of score on its own; see the engagement gate in
  // discoveryTags.js's "Trending Now" rule for the other half of this fix.
  ratingWeight: 1.5,
};

const RECENT_WINDOW_DAYS = 7; // what "recent7d" counts mean in the breakdown

// Decayed SUM of 1 per row within `lookbackDays`, grouped by productId, using
// Postgres to do the exp() math so we're not pulling raw rows into Node.
// `lookbackDays` bounds the query (nothing older matters at HALF_LIFE*6 or
// so — the weight is negligible) which keeps the scan cheap as history grows.
async function decayedCounts(table, dateColumn, halfLifeDays, lookbackDays, extraWhere = "") {
  const lambda = Math.log(2) / halfLifeDays;
  const rows = await prisma.$queryRawUnsafe(`
    SELECT "productId",
           COUNT(*)::int AS total,
           SUM(exp(-${lambda} * EXTRACT(EPOCH FROM (now() - "${dateColumn}")) / 86400))::float AS decayed,
           SUM(CASE WHEN "${dateColumn}" > now() - interval '${RECENT_WINDOW_DAYS} days' THEN 1 ELSE 0 END)::int AS recent
    FROM "${table}"
    WHERE "${dateColumn}" > now() - interval '${lookbackDays} days' ${extraWhere}
    GROUP BY "productId"
  `);
  return new Map(rows.map(r => [r.productId, { total: r.total, decayed: r.decayed, recent: r.recent }]));
}

async function computeSignals() {
  const lookback = (days) => Math.max(days * 6, 30); // ~6 half-lives is where weight rounds to ~0

  const [views, searchImpr, cartAdds, wishlistAdds, tryOns, tryOnConversions, purchases, reviews] = await Promise.all([
    decayedCounts("ProductView", "createdAt", HALF_LIFE_DAYS.views, lookback(HALF_LIFE_DAYS.views)),
    decayedCounts("ProductSearchImpression", "createdAt", HALF_LIFE_DAYS.searchImpressions, lookback(HALF_LIFE_DAYS.searchImpressions)),
    decayedCounts("CartItem", "createdAt", HALF_LIFE_DAYS.cartAdds, lookback(HALF_LIFE_DAYS.cartAdds)),
    decayedCounts("WishlistItem", "createdAt", HALF_LIFE_DAYS.wishlistAdds, lookback(HALF_LIFE_DAYS.wishlistAdds)),
    decayedCounts("TryOnSession", "createdAt", HALF_LIFE_DAYS.tryOns, lookback(HALF_LIFE_DAYS.tryOns)),
    decayedCounts("TryOnSession", "createdAt", HALF_LIFE_DAYS.tryOns, lookback(HALF_LIFE_DAYS.tryOns), `AND "converted" = true`),
    decayedCounts("OrderItem", "createdAt", HALF_LIFE_DAYS.purchases, lookback(HALF_LIFE_DAYS.purchases)),
    decayedCounts("Review", "createdAt", HALF_LIFE_DAYS.reviews, lookback(HALF_LIFE_DAYS.reviews)),
  ]);

  const productIds = new Set([
    ...views.keys(), ...searchImpr.keys(), ...cartAdds.keys(), ...wishlistAdds.keys(),
    ...tryOns.keys(), ...purchases.keys(), ...reviews.keys(),
  ]);

  // Ratings and per-product recency (for the "Just Added" tag threshold live
  // elsewhere in serialize/discoveryTags — this pass only needs id/rating).
  const products = await prisma.product.findMany({ select: { id: true, rating: true, trendScore: true } });
  for (const p of products) productIds.add(p.id);
  const ratingById = new Map(products.map(p => [p.id, p.rating]));
  const previousScoreById = new Map(products.map(p => [p.id, p.trendScore]));

  const zero = { total: 0, decayed: 0, recent: 0 };
  const out = new Map();

  for (const id of productIds) {
    const v = views.get(id) || zero;
    const s = searchImpr.get(id) || zero;
    const c = cartAdds.get(id) || zero;
    const w = wishlistAdds.get(id) || zero;
    const t = tryOns.get(id) || zero;
    const tc = tryOnConversions.get(id) || zero;
    const pu = purchases.get(id) || zero;
    const r = reviews.get(id) || zero;
    const rating = ratingById.get(id) ?? 4.5;

    const score =
      v.decayed * SIGNAL_WEIGHT.views +
      s.decayed * SIGNAL_WEIGHT.searchImpressions +
      c.decayed * SIGNAL_WEIGHT.cartAdds +
      w.decayed * SIGNAL_WEIGHT.wishlistAdds +
      t.decayed * SIGNAL_WEIGHT.tryOns +
      tc.decayed * SIGNAL_WEIGHT.tryOnConversionBonus +
      pu.decayed * SIGNAL_WEIGHT.purchases +
      r.decayed * SIGNAL_WEIGHT.reviewCountWeight +
      (rating - 3) * SIGNAL_WEIGHT.ratingWeight;

    const purchaseConversion = v.total > 0 ? pu.total / v.total : 0;
    const tryOnConversionRate = t.total > 0 ? tc.total / t.total : 0;

    out.set(id, {
      score: Math.max(0, score),
      previousScore: previousScoreById.get(id) || 0,
      breakdown: {
        views: v, searchImpressions: s, cartAdds: c, wishlistAdds: w,
        tryOns: t, tryOnConversions: tc, purchases: pu, reviews: r,
        rating, purchaseConversion, tryOnConversionRate,
      },
    });
  }
  return out;
}

/**
 * Ranks every product 0-100 by a single decayed signal (e.g. wishlistAdds).
 * Separate from the overall trendScore percentile — "Most Loved" should
 * reflect wishlist activity specifically, not the blended score, or it would
 * just be a second copy of "Trending Now".
 */
function percentileRank(entries, getValue) {
  const sorted = [...entries].sort((a, b) => getValue(b) - getValue(a));
  const n = sorted.length;
  const percentileById = new Map();
  sorted.forEach(([id], rank) => {
    percentileById.set(id, n > 1 ? Math.round((1 - rank / (n - 1)) * 100) : 100);
  });
  return percentileById;
}

/**
 * Recomputes trendScore for every product with any signal (and resets any
 * product that used to have signals but no longer does, e.g. after old
 * events age out of the lookback window). Returns a summary for logging.
 */
async function recalculate() {
  const signals = await computeSignals();
  const entries = [...signals.entries()];

  const overallPercentile = percentileRank(entries, ([, s]) => s.score);
  const wishlistPercentile = percentileRank(entries, ([, s]) => s.breakdown.wishlistAdds.decayed);
  const purchasePercentile = percentileRank(entries, ([, s]) => s.breakdown.purchases.decayed);
  const ratedPercentile = percentileRank(entries, ([, s]) => s.breakdown.reviews.decayed);
  // "Popular this week" blends the last-7-day raw counts across the signals
  // that indicate active interest right now, separately from the longer-
  // decay overall score — a product can be popular this week without yet
  // being "Trending Now" by the blended, longer-window measure.
  const popularity7dPercentile = percentileRank(entries, ([, s]) => {
    const b = s.breakdown;
    return b.views.recent + b.cartAdds.recent * 3 + b.tryOns.recent * 2 + b.purchases.recent * 5;
  });

  const updates = entries.map(([id, s]) => ({
    id,
    trendScore: s.score,
    trendScorePrevious: s.previousScore,
    trendScoreBreakdown: {
      ...s.breakdown,
      percentile: overallPercentile.get(id),
      wishlistPercentile: wishlistPercentile.get(id),
      purchasePercentile: purchasePercentile.get(id),
      ratedPercentile: ratedPercentile.get(id),
      popularity7dPercentile: popularity7dPercentile.get(id),
      computedAt: new Date().toISOString(),
    },
  }));

  // Prisma has no bulk-update-with-different-values, so this is one
  // statement per product. Fine at catalogue sizes this app runs at; if the
  // catalogue grows past a few thousand SKUs, swap for a single
  // UPDATE ... FROM (VALUES ...) raw statement.
  await prisma.$transaction(
    updates.map(u => prisma.product.update({
      where: { id: u.id },
      data: {
        trendScore: u.trendScore,
        trendScorePrevious: u.trendScorePrevious,
        trendScoreBreakdown: u.trendScoreBreakdown,
        trendScoreComputedAt: new Date(),
      },
    }))
  );

  const topScore = updates.reduce((max, u) => Math.max(max, u.trendScore), 0);
  return { productsScored: updates.length, topScore };
}

module.exports = { recalculate, computeSignals, HALF_LIFE_DAYS, SIGNAL_WEIGHT, RECENT_WINDOW_DAYS };
